-- 085_budget_approval_report.sql
-- Roadmap E.30: self-explanatory management report and evidence-backed variance context.
-- Historical benchmark engine is intentionally not invented here; availability is explicit.

CREATE TABLE IF NOT EXISTS public.project_budget_round_variance_contexts(
  round_id uuid NOT NULL REFERENCES public.project_budget_rounds(id) ON DELETE RESTRICT,
  budget_cycle_id uuid NOT NULL REFERENCES public.project_budget_cycles(id) ON DELETE RESTRICT,
  project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,
  work_group_id uuid NOT NULL,
  reason_code text NOT NULL CHECK(reason_code IN('MARKET_PRICE_INCREASE','LABOR_COST_INCREASE','QUANTITY_INCREASE','SCOPE_INCREASE','SPECIFICATION_UPGRADE','CURRENCY_IMPACT','LOGISTICS','REGULATORY_REQUIREMENT','DESIGN_CHANGE','PREVIOUS_BENCHMARK_NOT_COMPARABLE','BUDGET_METHODOLOGY_CHANGE','OTHER')),
  explanation text NOT NULL CHECK(btrim(explanation)<>'' AND char_length(explanation)<=2000),
  evidence_reference text NOT NULL CHECK(btrim(evidence_reference)<>'' AND char_length(evidence_reference)<=1000),
  open_question text NOT NULL DEFAULT '' CHECK(char_length(open_question)<=1000),
  revision integer NOT NULL CHECK(revision>0),updated_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(round_id,work_group_id)
);
CREATE TABLE IF NOT EXISTS public.project_budget_round_variance_context_events(
  id uuid PRIMARY KEY,round_id uuid NOT NULL,budget_cycle_id uuid NOT NULL,project_id bigint NOT NULL,work_group_id uuid NOT NULL,
  reason_code text NOT NULL,explanation text NOT NULL,evidence_reference text NOT NULL,open_question text NOT NULL,context_revision integer NOT NULL,
  actor_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(round_id,work_group_id)REFERENCES public.project_budget_round_variance_contexts(round_id,work_group_id)ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS project_budget_variance_context_cycle_idx ON public.project_budget_round_variance_contexts(budget_cycle_id,round_id);
ALTER TABLE public.project_budget_round_variance_contexts ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_budget_round_variance_context_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS project_budget_variance_contexts_select ON public.project_budget_round_variance_contexts;
CREATE POLICY project_budget_variance_contexts_select ON public.project_budget_round_variance_contexts FOR SELECT TO authenticated USING((lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id))OR EXISTS(SELECT 1 FROM public.project_budget_ownerships o WHERE o.budget_cycle_id=project_budget_round_variance_contexts.budget_cycle_id AND o.owner_user_id=auth.uid()));
DROP POLICY IF EXISTS project_budget_variance_context_events_select ON public.project_budget_round_variance_context_events;
CREATE POLICY project_budget_variance_context_events_select ON public.project_budget_round_variance_context_events FOR SELECT TO authenticated USING((lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id))OR EXISTS(SELECT 1 FROM public.project_budget_ownerships o WHERE o.budget_cycle_id=project_budget_round_variance_context_events.budget_cycle_id AND o.owner_user_id=auth.uid()));
REVOKE ALL ON TABLE public.project_budget_round_variance_contexts,public.project_budget_round_variance_context_events FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON TABLE public.project_budget_round_variance_contexts,public.project_budget_round_variance_context_events TO authenticated;

CREATE OR REPLACE FUNCTION public.save_budget_round_variance_context(p_round_id uuid,p_work_group_id uuid,p_reason_code text,p_explanation text,p_evidence_reference text,p_open_question text,p_expected_revision integer,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_round public.project_budget_rounds%ROWTYPE;v_cycle public.project_budget_cycles%ROWTYPE;v_existing public.project_budget_round_variance_contexts%ROWTYPE;v_request public.write_command_requests%ROWTYPE;v_result jsonb;v_revision integer;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';END IF;
 IF p_round_id IS NULL OR p_work_group_id IS NULL OR p_client_request_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_reason_code NOT IN('MARKET_PRICE_INCREASE','LABOR_COST_INCREASE','QUANTITY_INCREASE','SCOPE_INCREASE','SPECIFICATION_UPGRADE','CURRENCY_IMPACT','LOGISTICS','REGULATORY_REQUIREMENT','DESIGN_CHANGE','PREVIOUS_BENCHMARK_NOT_COMPARABLE','BUDGET_METHODOLOGY_CHANGE','OTHER')OR btrim(COALESCE(p_explanation,''))=''OR char_length(p_explanation)>2000 OR btrim(COALESCE(p_evidence_reference,''))=''OR char_length(p_evidence_reference)>1000 OR char_length(COALESCE(p_open_question,''))>1000 THEN RAISE EXCEPTION 'INVALID_BUDGET_VARIANCE_CONTEXT' USING ERRCODE='22023';END IF;
 SELECT * INTO v_round FROM public.project_budget_rounds WHERE id=p_round_id;IF v_round.id IS NULL THEN RAISE EXCEPTION 'BUDGET_ROUND_NOT_FOUND' USING ERRCODE='P0002';END IF;
 SELECT * INTO v_cycle FROM public.project_budget_cycles WHERE id=v_round.budget_cycle_id;
 IF lower((SELECT role FROM public.profiles WHERE id=v_uid))NOT IN('pm','admin')OR public.can_write_project(v_round.project_id)IS NOT TRUE THEN RAISE EXCEPTION 'BUDGET_REPORT_CONTEXT_FORBIDDEN' USING ERRCODE='42501';END IF;
 IF v_cycle.approval_state='APPROVED'OR EXISTS(SELECT 1 FROM public.project_budget_round_reviews WHERE round_id=p_round_id)THEN RAISE EXCEPTION 'BUDGET_REPORT_CONTEXT_LOCKED' USING ERRCODE='55000';END IF;
 IF v_cycle.current_round_number<>v_round.round_number OR v_cycle.round_state<>'ISSUED'THEN RAISE EXCEPTION 'BUDGET_REPORT_REQUIRES_CURRENT_ISSUED_ROUND' USING ERRCODE='55000';END IF;
 IF v_round.round_number=1 OR NOT EXISTS(SELECT 1 FROM public.project_budget_round_items current_item JOIN public.project_budget_rounds previous_round ON previous_round.budget_cycle_id=v_round.budget_cycle_id AND previous_round.round_number=v_round.round_number-1 JOIN public.project_budget_round_items previous_item ON previous_item.round_id=previous_round.id AND previous_item.work_group_id=current_item.work_group_id WHERE current_item.round_id=p_round_id AND current_item.work_group_id=p_work_group_id AND current_item.amount IS DISTINCT FROM previous_item.amount)THEN RAISE EXCEPTION 'BUDGET_VARIANCE_CONTEXT_REQUIRES_CHANGED_WORK_GROUP' USING ERRCODE='55000';END IF;
 INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(v_uid,'budget.save_variance_context',p_client_request_id,v_round.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT * INTO v_request FROM public.write_command_requests WHERE actor_id=v_uid AND operation='budget.save_variance_context'AND client_request_id=p_client_request_id;
 IF v_request.response IS NOT NULL THEN RETURN v_request.response||jsonb_build_object('idempotentReplay',true);END IF;
 SELECT * INTO v_existing FROM public.project_budget_round_variance_contexts WHERE round_id=p_round_id AND work_group_id=p_work_group_id FOR UPDATE;IF COALESCE(v_existing.revision,0)<>p_expected_revision THEN RAISE EXCEPTION 'BUDGET_VARIANCE_CONTEXT_REVISION_CONFLICT' USING ERRCODE='40001';END IF;v_revision:=p_expected_revision+1;
 INSERT INTO public.project_budget_round_variance_contexts(round_id,budget_cycle_id,project_id,work_group_id,reason_code,explanation,evidence_reference,open_question,revision,updated_by)VALUES(p_round_id,v_round.budget_cycle_id,v_round.project_id,p_work_group_id,p_reason_code,btrim(p_explanation),btrim(p_evidence_reference),btrim(COALESCE(p_open_question,'')),v_revision,v_uid)ON CONFLICT(round_id,work_group_id)DO UPDATE SET reason_code=EXCLUDED.reason_code,explanation=EXCLUDED.explanation,evidence_reference=EXCLUDED.evidence_reference,open_question=EXCLUDED.open_question,revision=EXCLUDED.revision,updated_by=EXCLUDED.updated_by,updated_at=now();
 INSERT INTO public.project_budget_round_variance_context_events VALUES(gen_random_uuid(),p_round_id,v_round.budget_cycle_id,v_round.project_id,p_work_group_id,p_reason_code,btrim(p_explanation),btrim(p_evidence_reference),btrim(COALESCE(p_open_question,'')),v_revision,v_uid,now());
 v_result:=jsonb_build_object('roundId',p_round_id,'workGroupId',p_work_group_id,'revision',v_revision);UPDATE public.write_command_requests SET response=v_result,completed_at=now()WHERE id=v_request.id;RETURN v_result||jsonb_build_object('idempotentReplay',false);
END;$$;

CREATE OR REPLACE FUNCTION public.get_budget_approval_report(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_project public.projects%ROWTYPE;v_cycle public.project_budget_cycles%ROWTYPE;v_round public.project_budget_rounds%ROWTYPE;v_previous public.project_budget_rounds%ROWTYPE;v_changed integer;v_unexplained integer;v_open integer;v_increase numeric;v_decrease numeric;v_changes jsonb;v_sections jsonb;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';END IF;SELECT * INTO v_project FROM public.projects WHERE id=p_project_id;SELECT * INTO v_cycle FROM public.project_budget_cycles WHERE project_id=p_project_id;IF v_cycle.id IS NULL OR lower((SELECT role FROM public.profiles WHERE id=v_uid))NOT IN('pm','admin')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION 'BUDGET_APPROVAL_REPORT_FORBIDDEN' USING ERRCODE='42501';END IF;
 SELECT * INTO v_round FROM public.project_budget_rounds WHERE budget_cycle_id=v_cycle.id AND round_number=v_cycle.current_round_number;SELECT * INTO v_previous FROM public.project_budget_rounds WHERE budget_cycle_id=v_cycle.id AND round_number=v_cycle.current_round_number-1;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('sectionCode',section.discipline_code,'sectionLabel',section.discipline_label,'amount',section.amount,'workGroupCount',section.work_group_count,'amountPerSqm',CASE WHEN COALESCE(v_project.store_size_sqm,0)>0 THEN round(section.amount/v_project.store_size_sqm,2)ELSE NULL END)ORDER BY section.discipline_code),'[]'::jsonb)INTO v_sections FROM(SELECT discipline_code,discipline_label,sum(amount)amount,count(*)work_group_count FROM public.project_budget_round_items WHERE round_id=v_round.id GROUP BY discipline_code,discipline_label)section;
 WITH changes AS(SELECT c.work_group_id,c.discipline_code,c.discipline_label,c.work_group_code,c.work_group_label,c.amount current_amount,p.amount previous_amount,c.amount-p.amount delta,ctx.reason_code,ctx.explanation,ctx.evidence_reference,ctx.open_question,ctx.revision context_revision FROM public.project_budget_round_items c JOIN public.project_budget_round_items p ON p.round_id=v_previous.id AND p.work_group_id=c.work_group_id LEFT JOIN public.project_budget_round_variance_contexts ctx ON ctx.round_id=c.round_id AND ctx.work_group_id=c.work_group_id WHERE c.round_id=v_round.id AND c.amount IS DISTINCT FROM p.amount)
 SELECT count(*),count(*)FILTER(WHERE reason_code IS NULL),count(*)FILTER(WHERE btrim(COALESCE(open_question,''))<>''),COALESCE(sum(delta)FILTER(WHERE delta>0),0),COALESCE(sum(delta)FILTER(WHERE delta<0),0),COALESCE(jsonb_agg(jsonb_build_object('workGroupId',work_group_id,'disciplineCode',discipline_code,'disciplineLabel',discipline_label,'workGroupCode',work_group_code,'workGroupLabel',work_group_label,'currentAmount',current_amount,'previousAmount',previous_amount,'delta',delta,'direction',CASE WHEN delta>0 THEN'INCREASE'ELSE'DECREASE'END,'reasonCode',reason_code,'explanation',explanation,'evidenceReference',evidence_reference,'openQuestion',open_question,'contextRevision',COALESCE(context_revision,0))ORDER BY abs(delta)DESC),'[]'::jsonb)INTO v_changed,v_unexplained,v_open,v_increase,v_decrease,v_changes FROM changes;
 RETURN jsonb_build_object('projectId',p_project_id,'roundId',v_round.id,'roundNumber',v_round.round_number,'currencyCode',v_round.currency_code,'projectAreaSqm',v_project.store_size_sqm,'workGroupCount',v_round.work_group_count,'totalProposedBudget',v_round.total_amount,'totalAmountPerSqm',CASE WHEN COALESCE(v_project.store_size_sqm,0)>0 THEN round(v_round.total_amount/v_project.store_size_sqm,2)ELSE NULL END,'sectionTotals',COALESCE(v_sections,'[]'::jsonb),'previousRoundTotal',v_previous.total_amount,'netChange',CASE WHEN v_previous.id IS NULL THEN NULL ELSE v_round.total_amount-v_previous.total_amount END,'changedWorkGroupCount',COALESCE(v_changed,0),'unexplainedVarianceCount',COALESCE(v_unexplained,0),'openQuestionCount',COALESCE(v_open,0),'totalIncrease',COALESCE(v_increase,0),'totalDecrease',COALESCE(v_decrease,0),'changes',COALESCE(v_changes,'[]'::jsonb),'benchmarkStatus','NOT_AVAILABLE','benchmarkMessage','Historical comparable-project engine is not implemented yet; no normal-range claim is made.','approvalReady',v_round.id IS NOT NULL AND COALESCE(v_unexplained,0)=0 AND COALESCE(v_open,0)=0,'approvalRule','No number without context. No variance without reason. No approval without evidence.');
END;$$;

CREATE OR REPLACE FUNCTION private.enforce_budget_approval_report_gate()RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
DECLARE v_round public.project_budget_rounds%ROWTYPE;v_previous uuid;v_missing integer;v_open integer;
BEGIN SELECT * INTO v_round FROM public.project_budget_rounds WHERE id=NEW.source_round_id;SELECT id INTO v_previous FROM public.project_budget_rounds WHERE budget_cycle_id=v_round.budget_cycle_id AND round_number=v_round.round_number-1;
 IF v_previous IS NOT NULL THEN SELECT count(*)FILTER(WHERE ctx.round_id IS NULL),count(*)FILTER(WHERE btrim(COALESCE(ctx.open_question,''))<>'')INTO v_missing,v_open FROM public.project_budget_round_items c JOIN public.project_budget_round_items p ON p.round_id=v_previous AND p.work_group_id=c.work_group_id LEFT JOIN public.project_budget_round_variance_contexts ctx ON ctx.round_id=c.round_id AND ctx.work_group_id=c.work_group_id WHERE c.round_id=v_round.id AND c.amount IS DISTINCT FROM p.amount;IF v_missing>0 THEN RAISE EXCEPTION 'BUDGET_APPROVAL_HAS_UNEXPLAINED_VARIANCE' USING ERRCODE='55000';END IF;IF v_open>0 THEN RAISE EXCEPTION 'BUDGET_APPROVAL_HAS_OPEN_QUESTIONS' USING ERRCODE='55000';END IF;END IF;RETURN NEW;
END;$$;
DROP TRIGGER IF EXISTS approved_budget_baseline_report_gate ON public.approved_budget_baselines;CREATE TRIGGER approved_budget_baseline_report_gate BEFORE INSERT ON public.approved_budget_baselines FOR EACH ROW EXECUTE FUNCTION private.enforce_budget_approval_report_gate();

REVOKE ALL ON FUNCTION public.save_budget_round_variance_context(uuid,uuid,text,text,text,text,integer,uuid),public.get_budget_approval_report(bigint)FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_budget_round_variance_context(uuid,uuid,text,text,text,text,integer,uuid),public.get_budget_approval_report(bigint)TO authenticated;
REVOKE ALL ON FUNCTION private.enforce_budget_approval_report_gate()FROM PUBLIC,anon,authenticated,service_role;
